namespace RecipeHub.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
            Ratings = [5, 4, 5, 4]
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale (or pancetta)\nEgg yolks\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a pan.\n3. Whisk egg yolks with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, add egg mixture and toss quickly.\n6. Serve immediately with extra pecorino.",
            Ratings = [5, 5, 4]
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nTomato sauce\nHeavy cream\nOnion\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or bake chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer.\n5. Stir in cream and garam masala.\n6. Add chicken pieces and simmer 10 minutes.\n7. Serve with basmati rice or naan.",
            Ratings = [5, 4, 5, 5]
        },
        new()
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
            Ingredients = "Rice noodles\nTofu\nBean sprouts\nScallions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nEggs",
            Steps = "1. Soak rice noodles in warm water for 30 minutes.\n2. Mix tamarind paste, fish sauce, and sugar for the sauce.\n3. Press and cube tofu, then pan-fry until golden.\n4. Scramble eggs in the same pan.\n5. Add noodles and sauce, toss to coat.\n6. Add bean sprouts and scallions.\n7. Serve with crushed peanuts and lime wedges.",
            Ratings = [4, 4, 3]
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer until thickened.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef, lettuce, tomato, and cheese.\n5. Top with sour cream and salsa.",
            Ratings = [4, 5, 4]
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt",
            Steps = "1. Halve and pit avocados, scoop into a bowl.\n2. Mash to desired consistency.\n3. Stir in diced onion, tomato, jalapeño, and cilantro.\n4. Add lime juice and salt to taste.\n5. Serve immediately with tortilla chips.",
            Ratings = [5, 5, 5, 4]
        },
        new()
        {
            Id = 7, Title = "Miso Soup", Category = "Asian",
            Ingredients = "Dashi stock\nWhite miso paste\nSilken tofu\nWakame seaweed\nScallions",
            Steps = "1. Bring dashi stock to a gentle simmer.\n2. Rehydrate wakame in water, then drain.\n3. Dissolve miso paste in a ladle of warm dashi.\n4. Add miso mixture back to pot (do not boil).\n5. Add cubed tofu and wakame.\n6. Serve garnished with sliced scallions.",
            Ratings = [4, 3, 4]
        },
        new()
        {
            Id = 8, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla extract\nAll-purpose flour\nBaking soda\nSalt\nChocolate chips",
            Steps = "1. Cream butter and sugars until fluffy.\n2. Beat in eggs and vanilla.\n3. Mix flour, baking soda, and salt, then combine with wet ingredients.\n4. Fold in chocolate chips.\n5. Drop spoonfuls onto baking sheets.\n6. Bake at 375°F for 9-11 minutes.\n7. Cool on baking sheet for 5 minutes.",
            Ratings = [5, 5, 4, 5]
        },
        new()
        {
            Id = 9, Title = "Dal Tadka", Category = "Indian",
            Ingredients = "Yellow lentils\nTurmeric\nTomatoes\nOnion\nGarlic\nCumin seeds\nMustard seeds\nDried red chilies\nGhee\nCilantro",
            Steps = "1. Wash lentils and cook with turmeric until soft.\n2. Heat ghee in a pan for tadka.\n3. Add cumin seeds, mustard seeds, and dried chilies.\n4. Add chopped onion and garlic, sauté until golden.\n5. Add diced tomatoes and cook down.\n6. Pour tadka over cooked lentils and stir.\n7. Garnish with cilantro and serve with rice.",
            Ratings = [4, 5, 4]
        },
    ];

    private int _nextId = 10;

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }
}

