        },
        new()
        {
            Id = 9, Title = "Dal Tadka", Category = "Indian",
            Ingredients = "Yellow lentils\nTurmeric\nTomatoes\nOnion\nGarlic\nCumin seeds\nMustard seeds\nDried red chilies\nGhee\nCilantro",
            Steps = "1. Wash lentils and cook with turmeric until soft.\n2. Heat ghee in a pan for tadka.\n3. Add cumin seeds, mustard seeds, and dried chilies.\n4. Add chopped onion and garlic, sauté until golden.\n5. Add diced tomatoes and cook down.\n6. Pour tadka over cooked lentils and stir.\n7. Garnish with cilantro and serve with rice.",
            Ratings = [4, 5, 4]
        },
    ];

    private int _nextId = 10;

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

