    <h1>Category not found</h1>
    <p>No recipes found for "@CategoryName".</p>
    <a href="/">Back to Home</a>
}
else
{
    <h1>@CategoryName Recipes</h1>
    <p><a href="/">← Back to all categories</a></p>

    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text text-muted">
                            @if (recipe.Ratings.Count > 0)
                            {
                                <span>@RenderStars(recipe.AverageRating) (@recipe.Ratings.Count ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = "";

    private IReadOnlyList<RecipeHub.Services.Recipe>? recipes;

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }

    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{RecipeId:int}"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (recipe is null)
{
    <h1>Recipe not found</h1>
    <a href="/">Back to Home</a>
}
else
{
    <p><a href="category/@recipe.Category">← Back to @recipe.Category</a></p>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <h3 class="mt-3">Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
    {
        <p>@step</p>
    }

    <hr />
    <h3>Rate this Recipe</h3>
    <StarRating RecipeId="recipe.Id" />
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private RecipeHub.Services.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(RecipeId);
    }
}

@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        int star = i;
        <span
            class="star @(star <= (hoverRating ?? selectedRating) ? "filled" : "")"
            @onclick="() => SubmitRating(star)"
            @onmouseover="() => hoverRating = star"
            @onmouseout="() => hoverRating = null"
            role="button"
            title="@star star(s)">
            @(star <= (hoverRating ?? selectedRating) ? "★" : "☆")
        </span>
    }
</div>

@if (submitted)
{
    <div class="text-success mt-1">
        <small>Thanks! You rated this @selectedRating star(s).</small>
    </div>
}

@if (recipe is not null)
{
    <div class="text-muted mt-1">
        <small>Average: @recipe.AverageRating.ToString("F1") / 5 (@recipe.Ratings.Count ratings)</small>
    </div>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating;
    private int? hoverRating;
    private bool submitted;
    private RecipeHub.Services.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(RecipeId);
    }

    private void SubmitRating(int rating)
    {
        selectedRating = rating;
        RecipeService.AddRating(RecipeId, rating);
        recipe = RecipeService.GetById(RecipeId);
        submitted = true;
    }
}

.star {
    font-size: 1.8rem;
    cursor: pointer;
    transition: color 0.15s;
    color: #ccc;
    user-select: none;
}

.star.filled {
    color: #ffc107;
}

.star:hover {
    transform: scale(1.2);
}

