@page "/submit"
@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted!</h4>
        <p>Your recipe "<strong>@Model!.Title</strong>" has been added.</p>
        <a href="recipe/@submittedId" class="btn btn-primary me-2">View Recipe</a>
        <button class="btn btn-outline-secondary" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="mb-3">
            <label class="form-label">Recipe Title</label>
            <InputText @bind-Value="Model!.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
            <ValidationMessage For="() => Model!.Title" />
        </div>

        <div class="mb-3">
            <label class="form-label">Category</label>
            <InputSelect @bind-Value="Model!.Category" class="form-select">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => Model!.Category" />
        </div>

        <div class="mb-3">
            <label class="form-label">Ingredients (one per line)</label>
            <InputTextArea @bind-Value="Model!.Ingredients" class="form-control" rows="6"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => Model!.Ingredients" />
        </div>

        <div class="mb-3">
            <label class="form-label">Steps</label>
            <InputTextArea @bind-Value="Model!.Steps" class="form-control" rows="6"
                placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients.&#10;3. ..." />
            <ValidationMessage For="() => Model!.Steps" />
        </div>

        <button type="submit" class="btn btn-success" disabled="@isSubmitting">
            @(isSubmitting ? "Submitting..." : "Submit Recipe")
        </button>
        <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    private RecipeFormModel? Model { get; set; }
    private bool submitted;
    private bool isSubmitting;
    private int submittedId;

    protected override void OnInitialized() => Model ??= new();

    private void HandleSubmit()
    {
        isSubmitting = true;

        var recipe = new RecipeHub.Services.Recipe
        {
            Title = Model!.Title!,
            Category = Model.Category!,
            Ingredients = Model.Ingredients!,
            Steps = Model.Steps!
        };

        RecipeService.AddRecipe(recipe);
        submittedId = recipe.Id;
        submitted = true;
        isSubmitting = false;
    }

    private void ResetForm()
    {
        Model = new();
        submitted = false;
    }

    private sealed class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        [System.ComponentModel.DataAnnotations.StringLength(200, MinimumLength = 3, ErrorMessage = "Title must be 3–200 characters.")]
        public string? Title { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string? Category { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the ingredients.")]
        public string? Ingredients { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the preparation steps.")]
        public string? Steps { get; set; }
    }
}

